SELECT DATE_TRUNC('WEEK', delivered_date) AS week_start, CASE WHEN cost >= 76 THEN 'LARGE' ELSE 'SMALL' END AS cost_tier, ROUND(SUM(cost) / NULLIF(COUNT(CASE WHEN carrier = 'Kerry' THEN 1 END), 0), 2) AS cost_per_kerry, SIZE(COLLECT_SET(carrier)) AS num_carriers, STDDEV_SAMP(cost) AS cost_stddev, STDDEV_SAMP(cost) AS cost_stddev_2, STDDEV_SAMP(cost) AS cost_stddev_3, RANK() OVER (PARTITION BY DATE_TRUNC('WEEK', delivered_date) ORDER BY ROUND(SUM(cost) / NULLIF(COUNT(CASE WHEN carrier = 'Kerry' THEN 1 END), 0), 2) DESC) AS cost_per_kerry_rank FROM shipments GROUP BY DATE_TRUNC('WEEK', delivered_date), CASE WHEN cost >= 76 THEN 'LARGE' ELSE 'SMALL' END ORDER BY cost_stddev DESC NULLS LAST;
